<?php
require_once __DIR__.'/../includes/functions.php'; require_admin(); $adminPage=true; $pageTitle='Manage rooms'; $message='';
if ($_SERVER['REQUEST_METHOD']==='POST') { $id=(int)($_POST['id']??0); $status=$_POST['status']??''; if(in_array($status,['available','maintenance'],true)){ $stmt=$pdo->prepare("UPDATE rooms SET status=? WHERE id=?"); $stmt->execute([$status,$id]); $message='Room status updated.'; } }
$rooms=$pdo->query("SELECT * FROM rooms ORDER BY id")->fetchAll(); include __DIR__.'/../includes/header.php';
?>
<section class="admin-wrap"><div class="container"><div class="eyebrow mb-3">Administration</div><h1 class="section-title mb-4">Manage rooms.</h1><?php if($message): ?><div class="alert alert-success"><?= e($message) ?></div><?php endif; ?><div class="table-responsive"><table class="table table-dark align-middle"><thead><tr><th>Room</th><th>Category</th><th>Rate/night</th><th>Max guests</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($rooms as $r): ?><tr><td><?= e($r['name']) ?></td><td><?= e($r['type']) ?></td><td>₱<?= number_format($r['price'],2) ?></td><td><?= (int)$r['max_guests'] ?></td><td><?= e($r['status']) ?></td><td><form method="post" class="d-flex gap-2"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><select class="form-select form-select-sm" name="status"><option value="available" <?= $r['status']==='available'?'selected':'' ?>>Available</option><option value="maintenance" <?= $r['status']==='maintenance'?'selected':'' ?>>Maintenance</option></select><button class="btn btn-gold btn-sm">Save</button></form></td></tr><?php endforeach; ?></tbody></table></div><a href="dashboard.php">← Back to dashboard</a></div></section>
